#!/usr/bin/env bash
# Copy or compare only the two Go stubs generated by :node_go_src.
set -euo pipefail

mode=${1:-}
if { [ "$mode" = --update ] && [ "$#" -ne 3 ]; } ||
	{ [ "$mode" = --check ] && [ "$#" -ne 5 ]; } ||
	{ [ "$mode" != --update ] && [ "$mode" != --check ]; }; then
	echo "usage: $0 --update GENERATED_MESSAGE GENERATED_SERVICE | --check GENERATED_MESSAGE GENERATED_SERVICE TRACKED_MESSAGE TRACKED_SERVICE" >&2
	exit 2
fi

# Resolve runfiles before changing into the checkout for writeback.
message=$(realpath "$2")
service=$(realpath "$3")
test -f "$message"
test -f "$service"

if [ "$mode" = --check ]; then
	diff -u "$4" "$message"
	diff -u "$5" "$service"
	echo "Go protobuf copies match :node_go_src (node.pb.go, node_grpc.pb.go)"
else
	cd "${BUILD_WORKSPACE_DIRECTORY:?run the update_go_stubs Bazel target}"
	package=projects/embervm/proto/embervm/node/v1
	# CI deliberately uses git add -u. New generated files need an explicit,
	# reviewed seed; never silently add a new output to the writeback set.
	git ls-files --error-unmatch -- "$package/node.pb.go" "$package/node_grpc.pb.go" >/dev/null
	cp "$message" "$package/node.pb.go"
	cp "$service" "$package/node_grpc.pb.go"
	echo "Updated the two tracked Go protobuf copies from :node_go_src"
fi
